// Proyección estricta RBAC/LOPDP: elimina físicamente el bloque financiero antes de enviar a Docentes/DECE/Inspección
const salida = [];
for (const item of $input.all()) {
  const d = item.json;
  const ped = d.vista_rbac_docente_dece_sin_datos_financieros || {};
  if (['ROJO', 'NARANJA', 'AMARILLO'].includes(ped.semaforo_docente)) {
    salida.push({ json: {
      canal_rbac: 'PEDAGOGICO_CERO_DATOS_FINANCIEROS',
      codigo_estudiante: d.codigo_estudiante,
      nombre_estudiante: d.nombre_estudiante,
      curso_paralelo: d.curso_paralelo,
      subnivel: d.subnivel,
      prioridad_ranking: d.prioridad_ranking,
      necesidad_educativa_nee: d.necesidad_educativa_nee,
      tiene_nee: d.necesidad_educativa_nee !== 'ninguna',
      vista_rbac_docente_dece_sin_datos_financieros: ped
    }});
  }
}
return salida;

// Proyección estricta Colecturía: elimina datos clínicos NEE/DECE y bloque pedagógico
return $input.all().map((item) => ({
  json: {
    canal_rbac: 'COLECTURIA_EXCLUSIVA_SIN_DECE',
    codigo_estudiante: item.json.codigo_estudiante,
    vista_rbac_colecturia_exclusiva_financiera: item.json.vista_rbac_colecturia_exclusiva_financiera
  }
}));

// Verifica la firma HMAC-SHA256 que pone el motor de E-Pakti: X-Epakti-Signature = "sha256=" + HMAC(secreto, bytes originales del cuerpo).
// Falla cerrado: sin secreto configurado, sin firma, firma falsa o envío vencido => se rechaza y NO se procesa nada.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
let ok = false, motivo = 'firma inválida', body = null;
try {
  const secret = $env.N8N_WEBHOOK_HMAC_SECRET || '';
  if (secret.length < 32) throw new Error('secreto HMAC no configurado en n8n');
  const sig = String(headers['x-epakti-signature'] || '');
  if (!sig.startsWith('sha256=')) throw new Error('falta X-Epakti-Signature');
  const ts = headers['x-epakti-timestamp'];                      // opcional: si el motor lo envía, se exige que sea reciente
  if (ts && Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('envío vencido');
  const raw = await this.helpers.getBinaryDataBuffer(0, 'data');  // bytes originales (opción Raw Body del Webhook)
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
  const a = Buffer.from(sig), b = Buffer.from(expected);
  if (!(a.length === b.length && crypto.timingSafeEqual(a, b))) throw new Error('firma inválida');
  const parsed = JSON.parse(raw.toString('utf8'));               // el cuerpo que se procesa es exactamente el que se firmó
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('cuerpo inválido');
  body = parsed;
  ok = true;                                                      // solo si la firma Y el cuerpo son válidos
} catch (e) { motivo = e.message; }
return [{ json: { firma_valida: ok, motivo_rechazo: ok ? null : motivo, ...(ok ? { headers, body } : {}) } }];

// Arma el informe por correo de cada alerta. RBAC: usa SOLO la vista del rol (pedagógica o Colecturía) que recibió el agente.
// Plantilla de correo: tablas + estilos en línea (Gmail/Outlook), 600 px, una columna en móvil, sin imágenes ni recursos externos.
const PED = '3A. Proyección RBAC Pedagógica (Elimina Todos los Campos Financieros)';
const COL = '3C. Proyección RBAC Colecturía (Solo Cartera Hogar, Elimina DECE/NEE)';
const origen = $prevNode.name;
const esCol = origen.startsWith('7.');
const base = esCol ? $(COL).item.json : $(PED).item.json;          // vista ya proyectada por rol
const cuerpo = $('1b. Verificar firma HMAC').first().json.body;
const sid = cuerpo.school_id;
const corte = cuerpo.fecha_corte_evaluacion || '';
const totalAlertas = (cuerpo.alertas_priorizadas_360 || []).length || cuerpo.cupo_alertas_emitidas;
const ruta = esCol ? ['COLECTURIA', 'CONVENIO_PAGO'] : origen.startsWith('6B.') ? ['INSPECCION', 'PLAN_ASISTENCIA'] : ['DOCENTE_TUTOR', 'TUTORIA_Y_ADAPTACION_NEE'];
const enfoque = esCol ? 'Colecturía' : origen.startsWith('6B.') ? 'Permanencia e Inspección' : 'Tutoría y DECE';

// --- utilidades ---
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const limpio = (s) => String(s ?? '').replace(/^\s*#+\s*/gm, '').replace(/^\s*[\*\-•]\s+/gm, '').replace(/[*_`#]+/g, '').replace(/\n{3,}/g, '\n\n').trim();
const num = (v) => (v == null || isNaN(Number(v))) ? null : Number(v);
const pct = (v) => num(v) == null ? '—' : num(v).toLocaleString('es-EC', { maximumFractionDigits: 1 }) + ' %';
const fechaLarga = (d) => { const t = new Date(d + 'T12:00:00'); return isNaN(t) ? esc(d) : t.toLocaleDateString('es-EC', { day: 'numeric', month: 'long', year: 'numeric' }); };

// --- tokens (estilo editorial) ---
const T = { tinta: '#111827', suave: '#4B5563', tenue: '#6B7280', linea: '#E5E7EB', fondo: '#F3F1EC', papel: '#FFFFFF', marca: '#1F1A3D', acento: '#5A3DE6' };
const SERIF = "Georgia,'Times New Roman',serif";
const SANS = 'Arial,Helvetica,sans-serif';
const SEM = {
  ROJO: { f: '#B42318', b: '#FEF3F2', n: 'Rojo', d: 'Intervención prioritaria' },
  NARANJA: { f: '#B54708', b: '#FFF6ED', n: 'Naranja', d: 'Atención esta semana' },
  AMARILLO: { f: '#8A6100', b: '#FEF7E0', n: 'Amarillo', d: 'Seguimiento preventivo' },
  VERDE: { f: '#067647', b: '#ECFDF3', n: 'Verde', d: 'Sin alerta' },
};
const sem = (c) => SEM[String(c || '').split(/[\s—-]/)[0].toUpperCase()] || { f: '#374151', b: '#F3F4F6', n: String(c || '—'), d: '' };
const chip = (c, txt) => { const s = sem(c); return `<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:${s.b};color:${s.f};font:700 12px ${SANS};letter-spacing:.04em;text-transform:uppercase;border:1px solid ${s.f}33">● ${esc(txt || s.n)}</span>`; };
const barra = (v, color, max = 100) => { const w = Math.max(2, Math.min(100, Math.round(((num(v) || 0) / max) * 100))); return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse"><tr><td style="background:#EEF0F3;border-radius:4px;height:8px;font-size:0;line-height:0"><table role="presentation" width="${w}%" cellpadding="0" cellspacing="0" style="border-collapse:collapse"><tr><td style="background:${color};border-radius:4px;height:8px;font-size:0;line-height:0">&nbsp;</td></tr></table></td></tr></table>`; };
const titulo = (t, sub) => `<tr><td style="padding:28px 32px 10px"><div style="font:700 11px ${SANS};letter-spacing:.14em;text-transform:uppercase;color:${T.acento}">${esc(t)}</div>${sub ? `<div style="font:13px/1.5 ${SANS};color:${T.tenue};margin-top:4px">${esc(sub)}</div>` : ''}</td></tr>`;
const bloque = (html) => `<tr><td style="padding:0 32px">${html}</td></tr>`;
const separador = `<tr><td style="padding:24px 32px 0"><div style="border-top:1px solid ${T.linea};font-size:0;line-height:0">&nbsp;</div></td></tr>`;
const metrica = (etq, valor, nota, color, v) => `<td class="col" valign="top" style="padding:0 6px 12px;width:50%"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ${T.linea};border-radius:10px;border-collapse:separate"><tr><td style="padding:14px 16px">
  <div style="font:12px/1.4 ${SANS};color:${T.tenue}">${esc(etq)}</div>
  <div style="font:700 28px/1.2 ${SERIF};color:${color};margin:4px 0 8px">${valor}</div>${barra(v, color)}
  <div style="font:12px/1.4 ${SANS};color:${T.tenue};margin-top:8px">${nota}</div></td></tr></table></td>`;

// --- texto del agente: ACCIONES (3 líneas «acción | responsable | plazo») y MENSAJE PARA LA FAMILIA ---
const bruto = String($json.output ?? $json.text ?? '');
const parte = (re) => { const m = bruto.match(re); return m ? m[1].trim() : ''; };
const bloqueAcc = parte(/ACCIONES\s*:?\s*([\s\S]*?)(?:MENSAJE[^\n:]*:|$)/i);
const mensaje = limpio(parte(/MENSAJE[^\n:]*:\s*([\s\S]*)$/i));
let acciones = bloqueAcc.split('\n').map((l) => limpio(l.replace(/^\s*\d+[\.\)]\s*/, ''))).filter(Boolean).slice(0, 3)
  .map((l) => { const [a, r, p] = l.split('|').map((x) => x.trim().replace(/^(Responsable|Plazo)\s*:\s*/i, '').trim()); return { a, r: r || '—', p: p || '—' }; });
const formatoOk = acciones.length === 3 && Boolean(mensaje);
if (!formatoOk) acciones = [];   // si el modelo no respetó el formato, se muestra su texto tal cual (limpio) para revisión humana

// --- contenido según rol ---
let semCodigo, semTexto, resumen, metricas, porQue, simul = '', asunto, preheader, destinatarios;
if (esCol) {
  const f = base.vista_rbac_colecturia_exclusiva_financiera || {};
  semCodigo = f.semaforo_pagos; semTexto = `${sem(semCodigo).n} · pagos`;
  resumen = `Representante <b>${esc(f.representante_codigo)}</b>${f.n_hermanos_en_plantel ? ` · ${esc(f.n_hermanos_en_plantel)} estudiante(s) en el plantel` : ''}. Tipología: ${esc((t => t.charAt(0) + t.slice(1).toLowerCase())(String(f.tipologia_morosidad || '—').replace(/^\d+\.\s*/, '')))}.`;
  metricas = metrica('Pago tardío o incumplimiento', pct(f.prob_incumplimiento_o_tardio_pct), 'Probabilidad para el próximo cobro', sem(semCodigo).f, f.prob_incumplimiento_o_tardio_pct)
           + metrica('Dos meses seguidos', pct(f.prob_dos_meses_incumpl_o_tardio_pct), 'Probabilidad de acumular mora', T.suave, f.prob_dos_meses_incumpl_o_tardio_pct);
  porQue = `<p style="margin:0;font:15px/1.6 ${SANS};color:${T.tinta}">${esc(f.por_que_morosidad_shap || '—')}</p>`;
  if (f.accion_colecturia) simul = titulo('Acción sugerida por el motor') + bloque(`<p style="margin:0;font:15px/1.6 ${SANS};color:${T.tinta}">${esc(f.accion_colecturia)}</p>`);
  destinatarios = f.acceso_restringido_solo_rol || 'Colecturía / Administración / Rectorado';
  asunto = `[PRUEBA] Colecturía · ${sem(semCodigo).n} · ${base.codigo_estudiante}`;
  preheader = `Pagos ${sem(semCodigo).n.toLowerCase()}: ${pct(f.prob_incumplimiento_o_tardio_pct)} de probabilidad de pago tardío. 3 acciones sugeridas.`;
} else {
  const v = base.vista_rbac_docente_dece_sin_datos_financieros || {};
  const s = v.simulacion_sensibilidad_puntaje_no_causal || {};
  semCodigo = v.semaforo_docente; semTexto = sem(semCodigo).n;
  resumen = `<b>${esc(base.curso_paralelo)}</b>${base.subnivel ? ` · ${esc(base.subnivel)}` : ''} · NEE: ${esc(base.necesidad_educativa_nee || 'ninguna')}${base.prioridad_ranking ? ` · prioridad <b>#${esc(base.prioridad_ranking)}</b>${totalAlertas ? ` de ${esc(totalAlertas)} alertas` : ''}` : ''}.`;
  const sp = sem(String(v.semaforo_permanencia || semCodigo)), sa = sem(String(v.semaforo_academico || semCodigo));
  metricas = metrica('Ausentismo recurrente', pct(v.prob_ausentismo_recurrente_pct), `Promedio del colegio: ${pct(v.prob_base_permanencia_pct)}`, sp.f, v.prob_ausentismo_recurrente_pct)
           + metrica('Riesgo de reprobar (2.º quimestre)', pct(v.prob_reprobacion_academica_q2_pct), esc(String(v.semaforo_academico || '').split('—')[1] || 'Riesgo académico').trim(), sa.f, v.prob_reprobacion_academica_q2_pct);
  const factores = (v.top_3_factores_shap_pedagogico || []).map((x) => { const m = String(x).match(/^(.*?)\s*\(([+−-]?\s*[\d.,]+)\s*pp\)\s*$/); const txt = (m ? m[1] : String(x)).replace(/^[^:]{0,40}:\s*/, '').replace(/>=\s*/g, '≥ ').replace(/<=\s*/g, '≤ ').replace(/\s*<\s*/g, ' menor a '); return { txt: txt.charAt(0).toUpperCase() + txt.slice(1), pp: m ? Number(m[2].replace(/[\s,−]/g, (c) => (c === ',' ? '.' : c === '−' ? '-' : ''))) : null }; });
  const maxPP = Math.max(10, ...factores.map((x) => Math.abs(x.pp || 0)));
  porQue = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">${factores.map((x, i) => `<tr><td valign="top" style="padding:10px 12px 10px 0;width:28px"><div style="width:26px;height:26px;border-radius:13px;background:${T.marca};color:#fff;font:700 13px/26px ${SANS};text-align:center">${i + 1}</div></td><td style="padding:10px 0;border-bottom:${i < factores.length - 1 ? `1px solid ${T.linea}` : '0'}"><div style="font:15px/1.5 ${SANS};color:${T.tinta}">${esc(x.txt)}</div>${x.pp != null ? `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:6px"><tr><td style="width:78%">${barra(Math.abs(x.pp), '#B42318', maxPP)}</td><td style="padding-left:10px;font:700 12px ${SANS};color:#B42318;white-space:nowrap">+${esc(x.pp.toLocaleString('es-EC', { maximumFractionDigits: 1 }))} pts</td></tr></table>` : ''}</td></tr>`).join('')}</table>
    <p style="margin:8px 0 0;font:12px/1.5 ${SANS};color:${T.tenue}">Cuánto suma cada factor a la probabilidad de ausentismo, según el modelo (SHAP).</p>`;
  if (s.palanca_pedagogica_sugerida && num(s.prob_post_sensibilidad_combinada_pct) != null) {
    simul = titulo('Qué bajaría el riesgo', `Palanca sugerida: ${s.palanca_pedagogica_sugerida}`) + bloque(`<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F7F8FA;border-radius:10px;border-collapse:separate"><tr><td style="padding:16px 18px">
      ${[['Hoy', v.prob_ausentismo_recurrente_pct, sp.f], ['Con plan de asistencia + tutoría', s.prob_post_sensibilidad_combinada_pct, '#067647']].map(([e, val, c], i) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:${i ? 12 : 0}px"><tr><td style="font:13px ${SANS};color:${T.suave};padding-bottom:6px">${e}</td><td align="right" style="font:700 15px ${SANS};color:${c};padding-bottom:6px;white-space:nowrap">${pct(val)}</td></tr><tr><td colspan="2">${barra(val, c)}</td></tr></table>`).join('')}
      <p style="margin:10px 0 0;font:12px/1.5 ${SANS};color:${T.tenue}">Escenario de sensibilidad del puntaje, no un efecto garantizado.</p></td></tr></table>`);
  }
  destinatarios = (v.destinatarios_n8n || []).join(', ') || 'Tutor, Inspección y DECE';
  asunto = `[PRUEBA] ${sem(semCodigo).n} · ${base.codigo_estudiante} (${base.curso_paralelo}) · ${v.foco_pedagogico || enfoque}`.trim();
  preheader = `${pct(v.prob_ausentismo_recurrente_pct)} de ausentismo (promedio ${pct(v.prob_base_permanencia_pct)}). ${formatoOk ? 'Primera acción: ' + acciones[0].a : 'Revise el plan sugerido.'}`;
}
const s0 = sem(semCodigo);

const accionesHtml = acciones.length
  ? acciones.map((x, i) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ${T.linea};border-left:4px solid ${i === 0 ? s0.f : T.acento};border-radius:8px;border-collapse:separate;margin-bottom:10px"><tr><td style="padding:14px 16px">
      <div style="font:700 11px ${SANS};letter-spacing:.1em;color:${T.tenue};text-transform:uppercase">Acción ${i + 1}${i === 0 ? ' · empezar por aquí' : ''}</div>
      <div style="font:600 16px/1.45 ${SANS};color:${T.tinta};margin:4px 0 10px">${esc(x.a)}</div>
      <span style="display:inline-block;margin:0 6px 4px 0;padding:3px 10px;border-radius:6px;background:#F1EEFD;color:#3B2A9E;font:12px ${SANS}"><b>Responsable:</b> ${esc(x.r)}</span><span style="display:inline-block;margin:0 0 4px;padding:3px 10px;border-radius:6px;background:#F3F4F6;color:${T.suave};font:12px ${SANS}"><b>Plazo:</b> ${esc(x.p)}</span>
    </td></tr></table>`).join('')
  : `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FFFBEB;border:1px solid #F5D78E;border-radius:8px;border-collapse:separate"><tr><td style="padding:14px 16px"><div style="font:700 12px ${SANS};color:#8A6100;margin-bottom:6px">El borrador de la IA no vino en el formato esperado. Revíselo antes de usarlo:</div><div style="font:14px/1.6 ${SANS};color:${T.tinta};white-space:pre-line">${esc(limpio(bruto))}</div></td></tr></table>`;

const familia = mensaje && formatoOk
  ? titulo('Mensaje sugerido para la familia', 'Borrador. No se envía hasta que una persona lo apruebe en E-Pakty.') + bloque(`<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FAF8F3;border-radius:10px;border-collapse:separate"><tr><td style="padding:18px 20px;font:italic 16px/1.65 ${SERIF};color:${T.tinta}">“${esc(mensaje)}”</td></tr></table>`)
  : '';

const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>${esc(asunto)}</title>
<style>@media (max-width:620px){.wrap{width:100%!important}.pad{padding-left:20px!important;padding-right:20px!important}.col{display:block!important;width:100%!important;padding:0 0 12px!important}}</style></head>
<body style="margin:0;padding:0;background:${T.fondo};-webkit-text-size-adjust:100%">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent">${esc(preheader)}&#8199;&#65279;&#847;&#8199;&#65279;&#847;&#8199;&#65279;&#847;</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${T.fondo}"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" class="wrap" width="600" cellpadding="0" cellspacing="0" style="width:600px;max-width:600px;background:${T.papel};border-radius:14px;overflow:hidden;border-collapse:separate">
  <tr><td style="background:${T.marca};padding:18px 32px" class="pad"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="font:700 15px ${SANS};letter-spacing:.16em;color:#fff;white-space:nowrap">E-PAKTY</td>
    <td align="right"><span style="display:inline-block;background:#F5B92A;color:${T.marca};padding:3px 9px;border-radius:5px;font:700 11px ${SANS};letter-spacing:.08em;white-space:nowrap">PRUEBA</span></td></tr></table></td></tr>
  <tr><td style="height:6px;background:${s0.f};font-size:0;line-height:0">&nbsp;</td></tr>
  <tr><td class="pad" style="padding:26px 32px 4px">
    <div style="font:12px/1.5 ${SANS};color:${T.tenue}">Informe de alerta temprana · ${esc(enfoque)} · corte ${fechaLarga(corte)}</div>
    <h1 style="margin:8px 0 10px;font:700 32px/1.15 ${SERIF};color:${T.tinta}">${esc(base.codigo_estudiante)}</h1>
    ${chip(semCodigo, semTexto)}${s0.d ? `<span style="font:13px ${SANS};color:${T.suave};margin-left:8px">${esc(s0.d)}</span>` : ''}
    <p style="margin:14px 0 0;font:15px/1.6 ${SANS};color:${T.suave}">${resumen}</p>
  </td></tr>
  <tr><td class="pad" style="padding:20px 26px 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>${metricas}</tr></table></td></tr>
  ${separador}
  ${titulo('Acciones para esta semana', 'Propuestas por la IA a partir del motor. Ajústelas a su contexto.')}
  ${bloque(accionesHtml)}
  ${separador}
  ${titulo(esCol ? 'Por qué está en seguimiento' : 'Por qué está en alerta')}
  ${bloque(porQue)}
  ${simul}
  ${familia}
  <tr><td class="pad" style="padding:28px 32px 8px" align="left"><a href="https://epakti.vercel.app/#panel" style="display:inline-block;background:${T.marca};color:#fff;text-decoration:none;font:700 14px ${SANS};padding:13px 22px;border-radius:8px">Abrir en E-Pakty →</a></td></tr>
  <tr><td class="pad" style="padding:20px 32px 26px;background:#FAFAF9;border-top:1px solid ${T.linea}">
    <p style="margin:0 0 6px;font:12px/1.6 ${SANS};color:${T.tenue}"><b style="color:${T.suave}">Para:</b> ${esc(destinatarios)} · ${esCol ? 'Confidencial: solo Colecturía y Rectorado. No incluye datos pedagógicos ni NEE.' : 'Vista pedagógica: no incluye datos financieros (LOPDP).'}</p>
    <p style="margin:0;font:12px/1.6 ${SANS};color:${T.tenue}">Borrador generado por IA (Amazon Nova Lite) a partir del motor de E-Pakty · ${esc(sid)}. Una persona debe revisarlo antes de cualquier contacto con la familia. Datos ficticios de prueba.</p>
  </td></tr>
</table></td></tr></table></body></html>`;
return { json: { school_id: sid, codigo_estudiante: base.codigo_estudiante, curso_paralelo: base.curso_paralelo || '', rol_ejecutor: ruta[0],
                 tipo_intervencion: ruta[1], asunto, html, formato_ok: formatoOk } };
